(1136223, 140848, 31505, '<td valign="top">my idea</td>', 'my idea', '2005-01-28 00:01:38.000000', NULL, 1),
(1136227, 140076, 15032, '<td valign="top">Make sure to level the photo so that the frames are parallel with the border of the picture</td>', 'Make sure to level the photo so that the frames are parallel with the border of the picture', '2005-01-28 00:02:59.000000', NULL, 1),
(1136228, 140581, 15032, '<td valign="top">I like the crowns... :)</td>', 'I like the crowns... :)', '2005-01-28 00:03:18.000000', NULL, 1),
(1136231, 140573, 17507, '<td valign="top">Great colors. Two suggestions: (1) try a softer light source to avoid glaring bright spots. (2) notice where all the lines point... down and out of the image. it might have worked better to have the three points converging somewhere in the middle parts of the image.</td>', 'Great colors. Two suggestions: (1) try a softer light source to avoid glaring bright spots. (2) notice where all the lines point... down and out of the image. it might have worked better to have the three points converging somewhere in the middle parts of the image.', '2005-01-28 00:04:33.000000', NULL, 1),
(1136233, 140526, 17507, '<td valign="top">The dude definitely adds life to the composition... but now there are four figures, plus a fifth in the background!<br/> <br/>So I''m not sure it meets the challenge that well.. but I love the colors so I''m giving it a 6.</td>', 'The dude definitely adds life to the composition... but now there are four figures, plus a fifth in the background! So I''m not sure it meets the challenge that well.. but I love the colors so I''m giving it a 6.', '2005-01-28 00:05:38.000000', NULL, 1),
(1136235, 140527, 20779, '<td valign="top">This is IT for me..</td>', 'This is IT for me..', '2005-01-28 00:06:03.000000', NULL, 1),
(1136238, 140484, 17507, '<td valign="top">Great colors and minimalism. If I were you I might have experimented with cloning out some of the structures... I feel like some are good but all of them are too many. Also, lots of JPEG artifacts in the sky- I suggest NeatImage! (And it''s free!)</td>', 'Great colors and minimalism. If I were you I might have experimented with cloning out some of the structures... I feel like some are good but all of them are too many. Also, lots of JPEG artifacts in the sky- I suggest NeatImage! (And it''s free!)', '2005-01-28 00:06:52.000000', NULL, 1),
(1136240, 140853, 15032, '<td valign="top">Nice shot, I would have liked to have seen 3 3''s, I almost did the same thing but with pocket 3''s, then changed at the last minute</td>', 'Nice shot, I would have liked to have seen 3 3''s, I almost did the same thing but with pocket 3''s, then changed at the last minute', '2005-01-28 00:07:18.000000', NULL, 1),
(1136241, 140801, 17507, '<td valign="top">Congratulations on your hardiness- but I''m not sure the effect of the title carries over well into the image :)</td>', 'Congratulations on your hardiness- but I''m not sure the effect of the title carries over well into the image :)', '2005-01-28 00:07:31.000000', NULL, 1),
(1136242, 140844, 25787, '<td valign="top">I wish my kids would sleep too.  Nice pic by the way.</td>', 'I wish my kids would sleep too.  Nice pic by the way.', '2005-01-28 00:07:43.000000', NULL, 1),
(1136243, 140336, 17507, '<td valign="top">Yow. great capture. I wonder how many dozens you took to get this one.</td>', 'Yow. great capture. I wonder how many dozens you took to get this one.', '2005-01-28 00:08:01.000000', NULL, 1),
(1136244, 140580, 26756, '<td valign="top">I''m not even entirely sure yet what I''m looking at, but it IS beautiful.  The horizontal line is a bit distracting but not so bad.</td>', 'I''m not even entirely sure yet what I''m looking at, but it IS beautiful.  The horizontal line is a bit distracting but not so bad.', '2005-01-28 00:08:04.000000', NULL, 1),
(1136245, 140334, 15032, '<td valign="top">Great shot, but a more uniform background would have helped a lot</td>', 'Great shot, but a more uniform background would have helped a lot', '2005-01-28 00:08:37.000000', NULL, 1),
(1136246, 140541, 17507, '<td valign="top">I like the way the three figures lead the eye back into the photo.<br/>Those benches are unbelievable! Here in California that sort of thing is utterly unheard of.</td>', 'I like the way the three figures lead the eye back into the photo.Those benches are unbelievable! Here in California that sort of thing is utterly unheard of.', '2005-01-28 00:08:45.000000', NULL, 1),
(1136248, 140334, 10080, '<td valign="top">What a great shot, with alot of meaning! The blur at the bottom really distracts me though. 8 for the overall!</td>', 'What a great shot, with alot of meaning! The blur at the bottom really distracts me though. 8 for the overall!', '2005-01-28 00:08:56.000000', NULL, 1),
(1136249, 140782, 17507, '<td valign="top">Seeing the title of this image, I realize that that must be the very reason for this challenge!</td>', 'Seeing the title of this image, I realize that that must be the very reason for this challenge!', '2005-01-28 00:09:13.000000', NULL, 1),
