(1136254, 140521, 17507, '<td valign="top">Great colors... not sure the horizon helps, though.</td>', 'Great colors... not sure the horizon helps, though.', '2005-01-28 00:12:35.000000', NULL, 1),
(1136256, 140547, 17507, '<td valign="top">Nice minimalism... but golly is that an ugly fork!</td>', 'Nice minimalism... but golly is that an ugly fork!', '2005-01-28 00:13:01.000000', NULL, 1),
(1136258, 140296, 26756, '<td valign="top">Very cool.  Like the subject you chose and the colors.  Goes well with the dark background.  I might have tried to keep the middle one just slighty more in focus but that''s just me.  Nice job.</td>', 'Very cool.  Like the subject you chose and the colors.  Goes well with the dark background.  I might have tried to keep the middle one just slighty more in focus but that''s just me.  Nice job.', '2005-01-28 00:13:48.000000', NULL, 1),
(1136260, 140601, 17507, '<td valign="top">the pinballs seem very much incidental to this picture. you have the eyes of your subject almost dead center, which draw much more attention than the pinballs in her hand. also, the balls are way close to the edge of the frame, kind of in tension with the edge. space on the upper left seems very dead.</td>', 'the pinballs seem very much incidental to this picture. you have the eyes of your subject almost dead center, which draw much more attention than the pinballs in her hand. also, the balls are way close to the edge of the frame, kind of in tension with the edge. space on the upper left seems very dead.', '2005-01-28 00:14:22.000000', NULL, 1),
(1136261, 140663, 17507, '<td valign="top">Wow. This is a great picture. The soft focus is lovely.</td>', 'Wow. This is a great picture. The soft focus is lovely.', '2005-01-28 00:14:50.000000', NULL, 1),
(1136263, 140828, 17507, '<td valign="top">This is soooo gloopy! Makes me want to splash it around and smear it all over clean surfaces.</td>', 'This is soooo gloopy! Makes me want to splash it around and smear it all over clean surfaces.', '2005-01-28 00:15:48.000000', NULL, 1),
(1136266, 140894, 29269, '<td valign="top">I think that the grass on the right could have been pushed further back, to take it out of focus and further accentuate the main object...</td>', 'I think that the grass on the right could have been pushed further back, to take it out of focus and further accentuate the main object...', '2005-01-28 00:17:24.000000', NULL, 1),
