(1136853, 140540, 18194, '<td valign="top">The idea is not bad and it does meet the challenge, but in the end the photo is not all that interesting.  It could also stand to be larger.</td>', 'The idea is not bad and it does meet the challenge, but in the end the photo is not all that interesting.  It could also stand to be larger.', '2005-01-28 10:55:21.000000', NULL, 1),
(1136855, 140889, 18194, '<td valign="top">For me a bit more DOF is called for in this photo.</td>', 'For me a bit more DOF is called for in this photo.', '2005-01-28 10:56:04.000000', NULL, 1),
