(1136913, 140525, 18194, '<td valign="top">I find that tThe bright gear thing that is in the jaws takes the attention away from the jaws.</td>', 'I find that tThe bright gear thing that is in the jaws takes the attention away from the jaws.', '2005-01-28 11:19:21.000000', NULL, 1),
