INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1137756, 140659, 4226, '<td valign="top">I have done a shot with the same title for hope challenge :D<br/>the petals seem to be a little blown out,not much detail in there. I like the way petals are separeted totally from background.</td>', 'I have done a shot with the same title for hope challenge :Dthe petals seem to be a little blown out,not much detail in there. I like the way petals are separeted totally from background.', '2005-01-28 19:32:39.000000', NULL, 1),
(1137761, 140568, 14735, '<td valign="top">Sometimes the simplest photo''s can be the best</td>', 'Sometimes the simplest photo''s can be the best', '2005-01-28 19:35:51.000000', NULL, 1),
(1137766, 140618, 14735, '<td valign="top">Is there a little subliminal message going here? Arer you using sex to get votes. Well it worked very nice photo</td>', 'Is there a little subliminal message going here? Arer you using sex to get votes. Well it worked very nice photo', '2005-01-28 19:39:01.000000', NULL, 1),
(1137767, 140778, 5354, '<td valign="top">I''m sorry, I have a real problem with this image. First of all it shows 4 attachments, OK 3 are heads and one is a heart I''ll accept that. My main problem though is that its so dull. there;s nothing to keep my attention, no artistry, no WOW Compositionally it hasn''t been thought through. I''m sorry if that offends in any way, but its my honest thoughts.<br/> <br/>Now how could we have made this something more appealing. How about having the chain on a nice pretty wrist, with a beautiful out of focus sunny/snowy/background, something like the winners of the Bokeh challenge produced. Or even have the bracelet being carressed by a pretty face. There are so many other ways of presenting this than on a plain old pullover.<br/> <br/>Hope some of that might have helped, thats the way it was intended.</td>', 'I''m sorry, I have a real problem with this image. First of all it shows 4 attachments, OK 3 are heads and one is a heart I''ll accept that. My main problem though is that its so dull. there;s nothing to keep my attention, no artistry, no WOW Compositionally it hasn''t been thought through. I''m sorry if that offends in any way, but its my honest thoughts. Now how could we have made this something more appealing. How about having the chain on a nice pretty wrist, with a beautiful out of focus sunny/snowy/background, something like the winners of the Bokeh challenge produced. Or even have the bracelet being carressed by a pretty face. There are so many other ways of presenting this than on a plain old pullover. Hope some of that might have helped, thats the way it was intended.', '2005-01-28 19:39:53.000000', NULL, 1),
(1137774, 140560, 5354, '<td valign="top">Please do go to the tutorial about resizing for submission. Thumbnail size submissions will always get a 3 or 4 from me, no matter how good or bad the image is, and its so easy to resize to 640 pixels on the long edge.<br/> <br/>As for the image, well the bottles, yep meets the challenge, but look at how you have arranged them - flat accross the fram. Theres endless possibilities for a little more dynamic setup here, especially if you are willing to play with the lighting too</td>', 'Please do go to the tutorial about resizing for submission. Thumbnail size submissions will always get a 3 or 4 from me, no matter how good or bad the image is, and its so easy to resize to 640 pixels on the long edge. As for the image, well the bottles, yep meets the challenge, but look at how you have arranged them - flat accross the fram. Theres endless possibilities for a little more dynamic setup here, especially if you are willing to play with the lighting too', '2005-01-28 19:44:29.000000', NULL, 1),
(1137782, 140785, 2223, '<td valign="top">I love this! I love how the eyes are lined up in an arc. Beautiful color!</td>', 'I love this! I love how the eyes are lined up in an arc. Beautiful color!', '2005-01-28 19:52:04.000000', NULL, 1),
(1137796, 140547, 5354, '<td valign="top">Hmmm, strange one this. I can''t say theres anything wrong with it as such, it just doesn''t take me to the WOW zone. Its like half a step off that.<br/> <br/>Having said that its way better than the majority in this challenge, Has to be in the top 30-40 or so for me. The background is what pulls this up from the croud.</td>', 'Hmmm, strange one this. I can''t say theres anything wrong with it as such, it just doesn''t take me to the WOW zone. Its like half a step off that. Having said that its way better than the majority in this challenge, Has to be in the top 30-40 or so for me. The background is what pulls this up from the croud.', '2005-01-28 20:00:35.000000', NULL, 1),
(1137798, 140478, 5354, '<td valign="top">I wondered about this one. Almost like a scene from star wars. Then I realised what it actually is. Excellent, not many people look up ;-)<br/>Great work - 7 (there arn''t many getting above 7 from me in this challenge!)</td>', 'I wondered about this one. Almost like a scene from star wars. Then I realised what it actually is. Excellent, not many people look up ;-)Great work - 7 (there arn''t many getting above 7 from me in this challenge!)', '2005-01-28 20:02:54.000000', NULL, 1),
