(1147120, 140581, 30818, '<td valign="top">I love how you captured the theme of Budweisers current advertising by turning the lids upside down...  of course, they''re ads show the crown as a water splash, but that is just so much more difficult :) 8</td>', 'I love how you captured the theme of Budweisers current advertising by turning the lids upside down...  of course, they''re ads show the crown as a water splash, but that is just so much more difficult :) 8', '2005-02-02 15:38:07.000000', NULL, 1),
(1147348, 140818, 30818, '<td valign="top">very nice! 7</td>', 'very nice! 7', '2005-02-02 16:56:15.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1147380, 140824, 14735, '<td valign="top">I cooked some of those up just last night. Love the set-up and angle</td>', 'I cooked some of those up just last night. Love the set-up and angle', '2005-02-02 17:13:23.000000', NULL, 1),
(1147391, 140225, 14735, '<td valign="top">Not sure if you noticed but if the cards were just a bit more to the left you would have had three threes, 3:15 and three colors cross the photo red black and white, but I see a bit of green there. Anyway great shot, loved it.</td>', 'Not sure if you noticed but if the cards were just a bit more to the left you would have had three threes, 3:15 and three colors cross the photo red black and white, but I see a bit of green there. Anyway great shot, loved it.', '2005-02-02 17:16:56.000000', NULL, 1),
(1147396, 140843, 14735, '<td valign="top">I really like the way all the threes are in a decorative design on the balls.</td>', 'I really like the way all the threes are in a decorative design on the balls.', '2005-02-02 17:18:28.000000', NULL, 1),
(1147398, 140755, 14735, '<td valign="top">The first thing that struck me is that you roll yours all the way out.</td>', 'The first thing that struck me is that you roll yours all the way out.', '2005-02-02 17:19:38.000000', NULL, 1),
(1147400, 140599, 14735, '<td valign="top">I love the angle and the light but I wish you could have gotten rid of the reflection in the middle of the first bottle. Very nice shot</td>', 'I love the angle and the light but I wish you could have gotten rid of the reflection in the middle of the first bottle. Very nice shot', '2005-02-02 17:21:10.000000', NULL, 1),
(1147409, 140577, 14735, '<td valign="top">Good idea but the light was too flat to make an impact. Keep shooting</td>', 'Good idea but the light was too flat to make an impact. Keep shooting', '2005-02-02 17:25:40.000000', NULL, 1),
(1147431, 140607, 18913, '<td valign="top">Really cool, creative and incredible.</td>', 'Really cool, creative and incredible.', '2005-02-02 17:37:59.000000', NULL, 1),
(1147439, 140284, 18913, '<td valign="top">Very moving and creative.</td>', 'Very moving and creative.', '2005-02-02 17:43:36.000000', NULL, 1),
(1147445, 140157, 18913, '<td valign="top">This one''s interesting after seeing all the other cliche ridden staged photos.  I would''ve preferred the orientation to be vertical so the viewer can take in some of the words on the page.  In this way the photo would''ve achieved immediate accessible depth and taken away from its ''threeness'' for a moment.  Still, I applaud your efforts.</td>', 'This one''s interesting after seeing all the other cliche ridden staged photos.  I would''ve preferred the orientation to be vertical so the viewer can take in some of the words on the page.  In this way the photo would''ve achieved immediate accessible depth and taken away from its ''threeness'' for a moment.  Still, I applaud your efforts.', '2005-02-02 17:48:07.000000', NULL, 1),
(1147451, 140449, 18913, '<td valign="top">Awesome....</td>', 'Awesome....', '2005-02-02 17:49:24.000000', NULL, 1),
(1147464, 140336, 23203, '<td valign="top">I can recognize the old-fashioned typewriter. Nice capture of its motion. Nice rusty duotone look. A tad brighter might help (or maybe its my LCD).. 8<br/> <br/> <br/></td>', 'I can recognize the old-fashioned typewriter. Nice capture of its motion. Nice rusty duotone look. A tad brighter might help (or maybe its my LCD).. 8  ', '2005-02-02 17:57:26.000000', NULL, 1),
(1147547, 140405, 32588, '<td valign="top">gorgeous.</td>', 'gorgeous.', '2005-02-02 18:42:58.000000', NULL, 1),
(1147559, 140575, 32588, '<td valign="top">everything about this photograph is just lovely.  it''s great that you have two instances of "three," too.  nice work.</td>', 'everything about this photograph is just lovely.  it''s great that you have two instances of "three," too.  nice work.', '2005-02-02 18:47:38.000000', NULL, 1),
(1147584, 140575, 13602, '<td valign="top">verry nice, I like this one!</td>', 'verry nice, I like this one!', '2005-02-02 19:06:01.000000', NULL, 1),
(1147614, 140878, 13602, '<td valign="top">Hmmm until I seen this I never figured the connection between this challenge and the fact that DPC is 3 years old. You are right! Wish the shot whas better :( Too many elements in it too many colors.</td>', 'Hmmm until I seen this I never figured the connection between this challenge and the fact that DPC is 3 years old. You are right! Wish the shot whas better :( Too many elements in it too many colors.', '2005-02-02 19:24:12.000000', NULL, 1),
(1147712, 140050, 4793, '<td valign="top">Yum, looks good enough to eat, nice shot</td>', 'Yum, looks good enough to eat, nice shot', '2005-02-02 20:15:16.000000', NULL, 1),
(1147717, 140562, 4793, '<td valign="top">Beautiful composition</td>', 'Beautiful composition', '2005-02-02 20:18:12.000000', NULL, 1),
(1147720, 140240, 4793, '<td valign="top">Very nice work</td>', 'Very nice work', '2005-02-02 20:18:47.000000', NULL, 1),
(1147722, 140652, 4793, '<td valign="top">Nice winter shot, nicely composed.</td>', 'Nice winter shot, nicely composed.', '2005-02-02 20:19:45.000000', NULL, 1),
(1147726, 140654, 4793, '<td valign="top">Beautiful colors and composition, nice details and clarity.</td>', 'Beautiful colors and composition, nice details and clarity.', '2005-02-02 20:21:55.000000', NULL, 1),
(1147728, 140782, 4793, '<td valign="top">Beautiful</td>', 'Beautiful', '2005-02-02 20:22:28.000000', NULL, 1),
(1147730, 140885, 4793, '<td valign="top">Beautiful</td>', 'Beautiful', '2005-02-02 20:23:04.000000', NULL, 1),
(1147734, 140574, 31214, '<td valign="top">Your idea is good but I find the dirty faucet too distracting.</td>', 'Your idea is good but I find the dirty faucet too distracting.', '2005-02-02 20:26:40.000000', NULL, 1),
(1147737, 140850, 31214, '<td valign="top">Clever idea.  You''ve taken what a lot of others would do (3 balls/balloons) and added your individual element (hair).  The composition is fantastic too.  I bet this wasn''t easy to do!  Congratulations.  10</td>', 'Clever idea.  You''ve taken what a lot of others would do (3 balls/balloons) and added your individual element (hair).  The composition is fantastic too.  I bet this wasn''t easy to do!  Congratulations.  10', '2005-02-02 20:28:25.000000', NULL, 1),
(1147740, 140753, 31214, '<td valign="top">clever composition and name!</td>', 'clever composition and name!', '2005-02-02 20:29:37.000000', NULL, 1),
(1147746, 140652, 31214, '<td valign="top">It''s almost as if the tree is leaning in to hear what the 3 grazers are chatting about.  Nice set up.</td>', 'It''s almost as if the tree is leaning in to hear what the 3 grazers are chatting about.  Nice set up.', '2005-02-02 20:31:02.000000', NULL, 1),
(1147751, 140827, 31214, '<td valign="top">Very nice.  Great set up with the shallow DOF for the chips.  I''d lose the ring though, it detracts from the point of the image.</td>', 'Very nice.  Great set up with the shallow DOF for the chips.  I''d lose the ring though, it detracts from the point of the image.', '2005-02-02 20:32:31.000000', NULL, 1),
(1147759, 140654, 31214, '<td valign="top">The angle you chose increases the effectiveness of this shot immensely.</td>', 'The angle you chose increases the effectiveness of this shot immensely.', '2005-02-02 20:34:36.000000', NULL, 1),
(1147772, 140635, 31214, '<td valign="top">Very crisp...excellent!</td>', 'Very crisp...excellent!', '2005-02-02 20:42:08.000000', NULL, 1),
(1147784, 140630, 31214, '<td valign="top">Nice picture...I like it a lot...but I see 4 trees?</td>', 'Nice picture...I like it a lot...but I see 4 trees?', '2005-02-02 20:49:25.000000', NULL, 1),
(1147786, 140116, 31214, '<td valign="top">Nice picture, but a stretch to meet the challenge. How do they eat those big nuts through the sock?</td>', 'Nice picture, but a stretch to meet the challenge. How do they eat those big nuts through the sock?', '2005-02-02 20:51:35.000000', NULL, 1),
(1147787, 140562, 19708, '<td valign="top">Very delicate, excellent lighting and a perfect composition for something that is generally looked down on photographically. One of my top ten favorites here. ((10))</td>', 'Very delicate, excellent lighting and a perfect composition for something that is generally looked down on photographically. One of my top ten favorites here. ((10))', '2005-02-02 20:51:39.000000', NULL, 1),
(1147788, 140884, 19708, '<td valign="top">Nicely composed and good control of the lighting. ((9))</td>', 'Nicely composed and good control of the lighting. ((9))', '2005-02-02 20:52:18.000000', NULL, 1),
(1147791, 140812, 31214, '<td valign="top">Too much digital noise.  Nice capture though.</td>', 'Too much digital noise.  Nice capture though.', '2005-02-02 20:53:25.000000', NULL, 1),
(1147792, 140282, 19708, '<td valign="top">Well seen and nicely toned. Composition is great! Something about these kind of shots I really like a lot. ((9))</td>', 'Well seen and nicely toned. Composition is great! Something about these kind of shots I really like a lot. ((9))', '2005-02-02 20:53:30.000000', NULL, 1),
(1147793, 140575, 19708, '<td valign="top">Interesting composition, but yet so simple. Well seen and nicely finished. ((8))</td>', 'Interesting composition, but yet so simple. Well seen and nicely finished. ((8))', '2005-02-02 20:54:27.000000', NULL, 1),
(1147794, 140602, 19708, '<td valign="top">Nice choice for Black &amp; White. Good exposure and detail in the snow, which is an accomplishment in itself. ((8))</td>', 'Nice choice for Black & White. Good exposure and detail in the snow, which is an accomplishment in itself. ((8))', '2005-02-02 20:55:12.000000', NULL, 1),
(1147813, 140654, 26756, '<td valign="top">I like this photo. It has a "stock" feel to it but I don''t mean that as a criticism.  I can just picture this being used somewhere.  I like that you took the time to use three different colored plates, and I like the arrangement.  You''re also left to decide...three plates, three cupcakes or three candles.</td>', 'I like this photo. It has a "stock" feel to it but I don''t mean that as a criticism.  I can just picture this being used somewhere.  I like that you took the time to use three different colored plates, and I like the arrangement.  You''re also left to decide...three plates, three cupcakes or three candles.', '2005-02-02 21:07:49.000000', NULL, 1),
(1147846, 140763, 4793, '<td valign="top">Lovely trio, your dof is very nice, good work.</td>', 'Lovely trio, your dof is very nice, good work.', '2005-02-02 21:55:46.000000', NULL, 1),
(1147848, 140848, 4793, '<td valign="top">Nice colors and composition</td>', 'Nice colors and composition', '2005-02-02 21:56:27.000000', NULL, 1),
(1147851, 140543, 4793, '<td valign="top">Nice Composition and colors</td>', 'Nice Composition and colors', '2005-02-02 21:58:27.000000', NULL, 1),
(1147856, 140884, 4793, '<td valign="top">My favorite, 10</td>', 'My favorite, 10', '2005-02-02 22:01:36.000000', NULL, 1),
(1147857, 140601, 4793, '<td valign="top">Beautiful</td>', 'Beautiful', '2005-02-02 22:01:48.000000', NULL, 1),
(1147858, 140792, 4793, '<td valign="top">Nice work</td>', 'Nice work', '2005-02-02 22:02:12.000000', NULL, 1),
(1147859, 140784, 4793, '<td valign="top">Cute shot, different</td>', 'Cute shot, different', '2005-02-02 22:02:41.000000', NULL, 1),
(1147862, 140656, 4793, '<td valign="top">Beautiful work</td>', 'Beautiful work', '2005-02-02 22:03:57.000000', NULL, 1),
(1147866, 140754, 4793, '<td valign="top">Nice composed shot, cute little people</td>', 'Nice composed shot, cute little people', '2005-02-02 22:04:53.000000', NULL, 1),
(1147870, 140806, 24951, '<td valign="top">Just beautiful and serene</td>', 'Just beautiful and serene', '2005-02-02 22:06:53.000000', NULL, 1),
(1147937, 140581, 9906, '<td valign="top">Not a bad high key shot.  Your reflections on the bottle though are a little distracting.  I can tell you where exactly you had at least two of your lights.  Also, the bottle on the left is not centered properly.  In a set up shot like this, these types of details are the key to making a good shot excellent!<br/>TC</td>', 'Not a bad high key shot.  Your reflections on the bottle though are a little distracting.  I can tell you where exactly you had at least two of your lights.  Also, the bottle on the left is not centered properly.  In a set up shot like this, these types of details are the key to making a good shot excellent!TC', '2005-02-02 22:47:29.000000', NULL, 1),
(1147939, 140618, 9906, '<td valign="top">Old fashioned word processor right?<br/>TC</td>', 'Old fashioned word processor right?TC', '2005-02-02 22:48:00.000000', NULL, 1),
(1147946, 140753, 9906, '<td valign="top">I''m torn between liking it this way, wanting more DOF or wanting less DOF.  Your composition is excellent.  Your choice of b/w treatment is impecible.  You have great contrasts and tonality.  It does look maybe a touch over sharpened.  Maybe just me though.  Nice job.<br/>TC</td>', 'I''m torn between liking it this way, wanting more DOF or wanting less DOF.  Your composition is excellent.  Your choice of b/w treatment is impecible.  You have great contrasts and tonality.  It does look maybe a touch over sharpened.  Maybe just me though.  Nice job.TC', '2005-02-02 22:51:35.000000', NULL, 1),
(1147950, 140091, 9906, '<td valign="top">This really has nothing to do with your photograph, but I''m always a little put off when one mentions DPC in their title.  To me this feels like sucking up and I don''t like people sucking up... I don''t let this effect my voting, but if I feel this way, I''m sure there are others who WILL let it effect their voting.<br/>TC</td>', 'This really has nothing to do with your photograph, but I''m always a little put off when one mentions DPC in their title.  To me this feels like sucking up and I don''t like people sucking up... I don''t let this effect my voting, but if I feel this way, I''m sure there are others who WILL let it effect their voting.TC', '2005-02-02 22:53:52.000000', NULL, 1),
(1147956, 140665, 9906, '<td valign="top">Done right, I really like back lit shots.  In this example though, there simply isn''t enough leafiness in the subject to truly take advantage of this style.<br/>TC</td>', 'Done right, I really like back lit shots.  In this example though, there simply isn''t enough leafiness in the subject to truly take advantage of this style.TC', '2005-02-02 22:55:29.000000', NULL, 1),
(1147958, 140828, 9906, '<td valign="top">I think I see you !  (wink) Very vivid colors and nice lighting.  However, there really isn''t a lot here to hold my attention for long.  Nice study though.<br/>TC</td>', 'I think I see you !  (wink) Very vivid colors and nice lighting.  However, there really isn''t a lot here to hold my attention for long.  Nice study though.TC', '2005-02-02 22:57:07.000000', NULL, 1),
(1147966, 140799, 9906, '<td valign="top">Your shooting angle looks a little awkward IMHO.  How did you get your coins to stand up so nicely?  Mine always fall over or aren''t oriented straight and I don''t have the patience to get it right.  You look like you may be just a touch oversharpened, but that may just be me.<br/>TC</td>', 'Your shooting angle looks a little awkward IMHO.  How did you get your coins to stand up so nicely?  Mine always fall over or aren''t oriented straight and I don''t have the patience to get it right.  You look like you may be just a touch oversharpened, but that may just be me.TC', '2005-02-02 22:59:07.000000', NULL, 1),
(1147979, 140630, 9906, '<td valign="top">IMHO this is a little two high key.  I would like to see more detail in the snow.  The trees by themselves don''t have enough pop to make me say wow and the dark spots in the snow without snow detail looks awkward.  Hard to expose well.  Believe me I know.<br/>TC</td>', 'IMHO this is a little two high key.  I would like to see more detail in the snow.  The trees by themselves don''t have enough pop to make me say wow and the dark spots in the snow without snow detail looks awkward.  Hard to expose well.  Believe me I know.TC', '2005-02-02 23:02:08.000000', NULL, 1),
(1148051, 140449, 26756, '<td valign="top">Fantastic interpretation of the challenge.  Very emotional shot.  I like the seemingly muted colors quite a bit.  I think the background could be slightly more out of focus to really make your subject pop a bit, but that''s pretty minor.  Great photo.</td>', 'Fantastic interpretation of the challenge.  Very emotional shot.  I like the seemingly muted colors quite a bit.  I think the background could be slightly more out of focus to really make your subject pop a bit, but that''s pretty minor.  Great photo.', '2005-02-02 23:38:30.000000', NULL, 1),
(1148117, 140340, 5728, '<td valign="top">Choice shot, I like your idea.</td>', 'Choice shot, I like your idea.', '2005-02-03 00:42:58.000000', NULL, 1),
(1148120, 140656, 5728, '<td valign="top">I personally would have not cropped it so tight, I would have left more room at the top where the water drop is. Good idea though, I thought the water was frozen when I first saw it, then I saw the drops :)</td>', 'I personally would have not cropped it so tight, I would have left more room at the top where the water drop is. Good idea though, I thought the water was frozen when I first saw it, then I saw the drops :)', '2005-02-03 00:44:32.000000', NULL, 1),
(1148121, 140785, 5728, '<td valign="top">Great!! Love the toning!</td>', 'Great!! Love the toning!', '2005-02-03 00:45:14.000000', NULL, 1),
(1148123, 140884, 5728, '<td valign="top">The lighting is very good!</td>', 'The lighting is very good!', '2005-02-03 00:45:32.000000', NULL, 1),
(1148132, 140811, 9906, '<td valign="top">Very elegant in it''s simplicity!  Love the fact that you have no hot spots (relfections) in the glass.  I desperatly want to see you lighting technique for this.  Great composition.  Just off centered enough.  The only (minor) thing I might change is moving the glasses apart just enough so you don''t see the right most glass in the left most glass but this is a nit at most.  Kudos!  Best in show so far.<br/>TC<br/>PS:  Is this desaturated or natural colors?  I think it''s desaturated.</td>', 'Very elegant in it''s simplicity!  Love the fact that you have no hot spots (relfections) in the glass.  I desperatly want to see you lighting technique for this.  Great composition.  Just off centered enough.  The only (minor) thing I might change is moving the glasses apart just enough so you don''t see the right most glass in the left most glass but this is a nit at most.  Kudos!  Best in show so far.TCPS:  Is this desaturated or natural colors?  I think it''s desaturated.', '2005-02-03 00:53:13.000000', NULL, 1),
(1148134, 140339, 9906, '<td valign="top">I thought you won if you fond the ball...<br/>TC</td>', 'I thought you won if you fond the ball...TC', '2005-02-03 00:53:42.000000', NULL, 1),
(1148135, 140755, 9906, '<td valign="top">Eeeewwww!<br/>TC</td>', 'Eeeewwww!TC', '2005-02-03 00:54:31.000000', NULL, 1),
(1148136, 140341, 5286, '<td valign="top">Nice idea, and it''s making me hunrgy!! Not as sharp as I would have liked though. And I don''t know that the pepper helps the image: I think it would have been cleaner without it.</td>', 'Nice idea, and it''s making me hunrgy!! Not as sharp as I would have liked though. And I don''t know that the pepper helps the image: I think it would have been cleaner without it.', '2005-02-03 00:54:32.000000', NULL, 1),
(1148137, 140827, 9906, '<td valign="top">I thought the big rage was Texas Hold ''em...  ;-)<br/>TC</td>', 'I thought the big rage was Texas Hold ''em...  ;-)TC', '2005-02-03 00:55:11.000000', NULL, 1),
(1148140, 140226, 9906, '<td valign="top">Cute!  Looks a little crooked though.  Nice graduated background.  Nice vivid colors.  A tad bit grainy.  This doesn''t add to this shot.<br/>TC</td>', 'Cute!  Looks a little crooked though.  Nice graduated background.  Nice vivid colors.  A tad bit grainy.  This doesn''t add to this shot.TC', '2005-02-03 00:57:53.000000', NULL, 1),
(1148141, 140594, 9906, '<td valign="top">Looks like a sideways ''M'' to me...<br/>TC</td>', 'Looks like a sideways ''M'' to me...TC', '2005-02-03 00:59:31.000000', NULL, 1),
(1148147, 140050, 9906, '<td valign="top">Nice composition.  You have three hot spots.  Moving your light to the sides and diffusing it more would help with this and give it much more depth.  THis is needed in a still life shot such as this.  Did you spray the apples with water?  It almost looks like they have wierd growths or something on them.  This is a great subject for lighting study.  Keep workin on it.  You almost got it.<br/>TC</td>', 'Nice composition.  You have three hot spots.  Moving your light to the sides and diffusing it more would help with this and give it much more depth.  THis is needed in a still life shot such as this.  Did you spray the apples with water?  It almost looks like they have wierd growths or something on them.  This is a great subject for lighting study.  Keep workin on it.  You almost got it.TC', '2005-02-03 01:03:09.000000', NULL, 1),
(1148151, 140525, 9906, '<td valign="top">Except for your title, I don''t see a relationship to the challenge topic.  I''m assuming it''s there, just a little essoteric for this viewing audience...<br/>TC</td>', 'Except for your title, I don''t see a relationship to the challenge topic.  I''m assuming it''s there, just a little essoteric for this viewing audience...TC', '2005-02-03 01:06:21.000000', NULL, 1),
(1148192, 140607, 19708, '<td valign="top">Very unique and interesting shot. Well seen. I''ll be looking at the info on this as I''m curious as to the camera &amp; exposure specifics. Well done. ((8))</td>', 'Very unique and interesting shot. Well seen. I''ll be looking at the info on this as I''m curious as to the camera & exposure specifics. Well done. ((8))', '2005-02-03 01:42:52.000000', NULL, 1),
(1148194, 140642, 19708, '<td valign="top">Nice mood set with the tone used.  Wonder if you had to wait long to get three people in there at the same time. Candid I hope. Nicely done. ((8))</td>', 'Nice mood set with the tone used.  Wonder if you had to wait long to get three people in there at the same time. Candid I hope. Nicely done. ((8))', '2005-02-03 01:44:40.000000', NULL, 1),
(1148297, 140478, 25571, '<td valign="top">This had the potential of a great picture, but unfortunatly, the colours are weak, its missing some saturation to bring the beige to life. Also there is too much grain on the shot due to shadoes. Also, i dont like the fact that the picture is not leveled. If those balls are in fact lamps, it wouldve made for a great night shot with lighting.</td>', 'This had the potential of a great picture, but unfortunatly, the colours are weak, its missing some saturation to bring the beige to life. Also there is too much grain on the shot due to shadoes. Also, i dont like the fact that the picture is not leveled. If those balls are in fact lamps, it wouldve made for a great night shot with lighting.', '2005-02-03 03:50:50.000000', NULL, 1),
(1148299, 140354, 25571, '<td valign="top">I get the frame idea, which is quite unique, unfortunatly, it wouldve been more interesting if the picture followed the theme, which it doesnt. Also i find the picture a bit dull in colours (i understand its during winter). The picture is nice and well leveled, but just doesnt follow the theme or brings the exclamation it should.</td>', 'I get the frame idea, which is quite unique, unfortunatly, it wouldve been more interesting if the picture followed the theme, which it doesnt. Also i find the picture a bit dull in colours (i understand its during winter). The picture is nice and well leveled, but just doesnt follow the theme or brings the exclamation it should.', '2005-02-03 03:52:39.000000', NULL, 1),
(1148300, 140443, 25571, '<td valign="top">very interesting concept. I only wished the &lt;model&gt; wouldve better represent the theme (as in 3 models). This has enormous potential for a Movie poster of sort. Too bad this idea wasnt brough up for the movie poster challenge!</td>', 'very interesting concept. I only wished the <model> wouldve better represent the theme (as in 3 models). This has enormous potential for a Movie poster of sort. Too bad this idea wasnt brough up for the movie poster challenge!', '2005-02-03 03:53:56.000000', NULL, 1),
(1148302, 140234, 25571, '<td valign="top">Interesting idea, but unfortunatly, i find the &lt;crop&gt; very bad. Following the theme, the models face is irrelevant, and doesnt bring anything to the earing. A more direct approach to the Earing wouldve done great for the challenge. Also i find the b&amp;w very dull. I would recommend playing with contrast slightly.</td>', 'Interesting idea, but unfortunatly, i find the <crop> very bad. Following the theme, the models face is irrelevant, and doesnt bring anything to the earing. A more direct approach to the Earing wouldve done great for the challenge. Also i find the b&w very dull. I would recommend playing with contrast slightly.', '2005-02-03 03:56:07.000000', NULL, 1),
(1148304, 140091, 25571, '<td valign="top">Very unimaginative and unartistic shot. Lighting is dull and doesnt give picture any credits. The picture is not leveled either. This shot, from a totaly darken room couldve brought better results. gl.</td>', 'Very unimaginative and unartistic shot. Lighting is dull and doesnt give picture any credits. The picture is not leveled either. This shot, from a totaly darken room couldve brought better results. gl.', '2005-02-03 03:57:38.000000', NULL, 1),
